+
+	p4 := Product{Code: "after_save_error", Price: 100}
+	db.Save(&p4)
+	if err := db.First(&Product{}, "code = ?", "after_save_error").Error; err == nil {
+		t.Errorf("Record should be reverted if get an error in after save callback", err)
