+func (role *Role) Scan(value interface{}) error {
+	switch v := value.(type) {
+	case []uint8:
+		role.Name = string(v)
+	case string:
+		role.Name = v
+	default:
+		role.Name = fmt.Sprintf("%s", v)
+	}
+	return nil
+}
