+	}
+
+	db.Delete(&p)
+	if !reflect.DeepEqual(p.GetCallTimes(), []int64{1, 2, 1, 1, 0, 0, 1, 1, 2}) {
+		t.Errorf("After delete callbacks should be invoked successfully, %v", p.GetCallTimes())
